import sys

data = sys.stdin.read().split()
T = int(data[0])
segs = [(int(data[1 + i * 2]), int(data[2 + i * 2])) for i in range(T)]
s = sorted(segs)
o = []
for l, r in s:
    if o and l <= o[-1][1]:
        if r > o[-1][1]:
            o[-1][1] = r
    else:
        o.append([l, r])
for l, r in o:
    print(l, r)

